import 'package:flutter/material.dart';
import '../models/task.dart'; import '../services/api_service.dart'; import 'login_screen.dart';
class TaskScreen extends StatefulWidget{const TaskScreen({super.key});State<TaskScreen> createState()=>_S();}
class _S extends State<TaskScreen>{late Future<List<Task>> data; String filter='all'; void load()=>setState(()=>data=ApiService.tasks()); @override void initState(){super.initState();data=ApiService.tasks();}
 Future<void> editor([Task? t]) async{final title=TextEditingController(text:t?.title),desc=TextEditingController(text:t?.description);String status=t?.status??'todo',priority=t?.priority??'medium';final save=await showDialog<bool>(context:context,builder:(c)=>StatefulBuilder(builder:(c,setD)=>AlertDialog(title:Text(t==null?'New Task':'Edit Task'),content:SingleChildScrollView(child:Column(children:[TextField(controller:title,decoration:const InputDecoration(labelText:'Title')),TextField(controller:desc,decoration:const InputDecoration(labelText:'Description')),DropdownButtonFormField(value:status,items:const [DropdownMenuItem(value:'todo',child:Text('To Do')),DropdownMenuItem(value:'progress',child:Text('In Progress')),DropdownMenuItem(value:'done',child:Text('Done'))],onChanged:(v)=>setD(()=>status=v!),decoration:const InputDecoration(labelText:'Status')),DropdownButtonFormField(value:priority,items:const [DropdownMenuItem(value:'low',child:Text('Low')),DropdownMenuItem(value:'medium',child:Text('Medium')),DropdownMenuItem(value:'high',child:Text('High'))],onChanged:(v)=>setD(()=>priority=v!),decoration:const InputDecoration(labelText:'Priority'))])),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(c,true),child:const Text('Save'))]))); if(save!=true||title.text.trim().isEmpty)return;if(t==null)await ApiService.create({'title':title.text.trim(),'description':desc.text.trim(),'status':status,'priority':priority});else{t.title=title.text.trim();t.description=desc.text.trim();t.status=status;t.priority=priority;await ApiService.update(t);}load();}
 Widget build(c)=>Scaffold(appBar:AppBar(title:const Text('My Tasks'),actions:[IconButton(onPressed:()async{await ApiService.logout();if(mounted)Navigator.pushReplacement(context,MaterialPageRoute(builder:(_)=>const LoginScreen()));},icon:const Icon(Icons.logout))]),floatingActionButton:FloatingActionButton.extended(onPressed:()=>editor(),icon:const Icon(Icons.add),label:const Text('Add Task')),body:Column(children:[Padding(padding:const EdgeInsets.all(12),child:DropdownButtonFormField(value:filter,decoration:const InputDecoration(labelText:'Filter',border:OutlineInputBorder()),items:const [DropdownMenuItem(value:'all',child:Text('All')),DropdownMenuItem(value:'todo',child:Text('To Do')),DropdownMenuItem(value:'progress',child:Text('In Progress')),DropdownMenuItem(value:'done',child:Text('Done'))],onChanged:(v)=>setState(()=>filter=v!))),Expanded(child:FutureBuilder<List<Task>>(future:data,builder:(c,s){if(s.connectionState!=ConnectionState.done)return const Center(child:CircularProgressIndicator());if(s.hasError)return Center(child:Text('${s.error}'));final all=s.data??[],list=filter=='all'?all:all.where((x)=>x.status==filter).toList();if(list.isEmpty)return const Center(child:Text('No tasks yet. Tap Add Task.'));return RefreshIndicator(onRefresh:()async=>load(),child:ListView.builder(itemCount:list.length,itemBuilder:(c,i){final t=list[i];return Card(margin:const EdgeInsets.symmetric(horizontal:12,vertical:6),child:ListTile(onTap:()=>editor(t),leading:Icon(t.status=='done'?Icons.check_circle:t.status=='progress'?Icons.timelapse:Icons.radio_button_unchecked),title:Text(t.title),subtitle:Text('${t.status.toUpperCase()} • ${t.priority.toUpperCase()}\n${t.description}',maxLines:2),isThreeLine:true,trailing:IconButton(icon:const Icon(Icons.delete_outline),onPressed:()async{await ApiService.delete(t.id);load();})));}));}))]));}
